package android.media;public class AudioManager {public boolean speaker;public int spdifLevel=4,speakerLevel=8,speechLevel=8;public int writes;public int getStreamMaxVolume(int stream){return 15;}public int getStreamVolume(int stream){return stream==3?(speaker?speakerLevel:spdifLevel):speechLevel;}public void setStreamVolume(int stream,int level,int flags){writes++;if(stream==3){if(speaker)speakerLevel=level;else spdifLevel=level;}else speechLevel=level;}}